const flowHelpers = global.get("flowHelpers");
if (!flowHelpers) {
    msg.statusCode = 500;
    msg.payload = { error: "flow_helpers_unavailable", message: "Boot-Flow pruefen" };
    return [null, msg];
}

const payload = flowHelpers.readPayloadObject(msg.payload);
const deviceId = typeof payload.device_id === "string" ? payload.device_id.trim() : "";
if (!deviceId) {
    msg.statusCode = 400;
    msg.payload = { error: "device_id_required", message: "device_id ist ein Pflichtfeld" };
    return [null, msg];
}

const rawType = typeof payload.contact_type === "string" ? payload.contact_type.trim().toLowerCase() : "";
const normalizedType = rawType === "door" || rawType === "tuer" || rawType === "tür"
    ? "door"
    : rawType === "window" || rawType === "fenster"
        ? "window"
        : "";

if (!normalizedType) {
    msg.statusCode = 400;
    msg.payload = { error: "contact_type_invalid", message: "contact_type muss window oder door sein" };
    return [null, msg];
}

const updatedAt = new Date().toISOString();
msg.dashboardContactTypeUpdate = { device_id: deviceId, contact_type: normalizedType, updated_at: updatedAt };
msg.params = [normalizedType, updatedAt, deviceId];
return [msg, null];

const update = msg.dashboardContactTypeUpdate || {};
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const row = rows.length > 0 ? rows[0] : null;
if (!row) {
    msg.statusCode = 404;
    msg.payload = { error: "device_not_found", message: "Geraet nicht in der Datenbank gefunden", device_id: update.device_id || null };
    return msg;
}
msg.statusCode = 200;
msg.payload = {
    device_id: row.device_id || update.device_id || null,
    contact_type: row.dashboard_contact_type || update.contact_type || null,
    updated_at: row.updated_at || update.updated_at || new Date().toISOString()
};
return msg;
